def top_k(query_vec: list, chunk_vecs: list, k: int) -> list:
    """Return indices of the k most similar chunks, best first.
    All vectors are normalized, so dot product == cosine similarity."""
    def dot(u, v):
        return sum(x * y for x, y in zip(u, v))

    scores = [dot(query_vec, c) for c in chunk_vecs]
    ranked = sorted(range(len(chunk_vecs)), key=lambda i: scores[i], reverse=True)
    return ranked[:k]

vecs = [[0.9, 0.44], [0.0, 1.0], [0.7, 0.71], [1.0, 0.0]]
print(top_k([1.0, 0.0], vecs, 2))
